arguments.command:
python3 -c "
# In Python's str.format(), what does }} do?
try:
    result = 'hello {{there}}'.format()
    print('Case 1:', result)
except Exception as e:
    print('Case 1 error:', e)

try:
    result = 'hello {}'.format('world')
    print('Case 2:', result)
except Exception as e:
    print('Case 2 error:', e)

# Check if }} is valid at all
try:
    result = 'close }} brace'.format()
    print('Case 3:', result)
except Exception as e:
    print('Case 3 error:', e)

# Check } followed by something else
try:
    result = '{x} }'.format(x='hello')
    print('Case 4:', result)
except Exception as e:
    print('Case 4 error:', e)
"
